/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: TrackTitleMember, DistinctiveTrackTitle
 *   Functions: trackTitleText, trackTitleWeight, distinctiveTrackTitles
 *   Constants: TRACK_TITLE_MIN_WEIGHT, UNCREDITED_TRACK_TITLE_MIN_WEIGHT, GENERIC_TRACK_TITLES
 * Internal
 *   Functions: isRecord, fold, cleanTrackTitle, trailingSegment, peelTrackTitle, fileNameShaped
 *   Constants: genericTitles, brackets, dashes, versionMarker, mrMarker, noteWord, audioExtension,
 *              trackNumberPrefix, heavy, counted
 * @end-catalog */

/**
 * Pure picker of an existing Album's distinctive saved Track titles for MusicBrainz recording searches (lookupQueryPlanner.ts):
 * each title cleaned like tag text and without its trailing version or featuring notes, generic, instrumental, file-name-shaped,
 * repeated and light titles skipped, the rest ranked by weight, then Album order. Total on malformed input. It never receives a
 * draft value, and a member's retained original filename is read only to skip a title equal to it; no filename is ever returned.
 */
import { METADATA_LOOKUP_LIMITS } from './lookupContract';
import { cleanLookupTerm } from './lookupIdentifiers';

/** A title lighter than this is never picked. */
export const TRACK_TITLE_MIN_WEIGHT = 4;
/** A title searched without an Artist must weigh at least this, so short common titles never flood the reserved release lookups. */
export const UNCREDITED_TRACK_TITLE_MIN_WEIGHT = 8;
/**
 * Generic titles never searched (published in docs/features/admin-workbench.md, What lookup sends); compared folded, after
 * trailing digits are removed, so `Interlude 2` and `Track01` are generic too.
 */
export const GENERIC_TRACK_TITLES: readonly string[] = Object.freeze([
    'intro', 'introduction', 'outro', 'interlude', 'prelude', 'prologue', 'epilogue', 'overture', 'skit', 'reprise', 'bonus', 'bonus track',
    'hidden track', 'secret track', 'untitled', 'untitled track', 'no title', 'instrumental', 'inst', 'karaoke', 'off vocal', 'backing track', 'tv size', 'track',
    'イントロ', 'アウトロ', 'インタールード', 'インスト', 'インストゥルメンタル', 'オフボーカル', 'カラオケ', 'ボーナストラック', '無題', 'トラック',
    '前奏', '序曲', '间奏', '間奏', '尾声', '尾聲', '伴奏', '纯音乐', '純音樂', '无题', '未命名',
    '인트로', '아웃트로', '반주', '연주곡'
]);
/**
 * One source track as a review captured it: its saved title, its retained original filename and the Artist name its search is
 * credited to (its own first non-placeholder primary Artist name, else the Album's), or null.
 */
export type TrackTitleMember = { title: unknown; originalFileName: unknown; artist: string | null };
/** A picked title without its trailing notes, its member's credited Artist name (or null) and its weight. */
export type DistinctiveTrackTitle = { text: string; artist: string | null; weight: number };

const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
/** Folded for comparison: compatibility forms, lower case, and no punctuation, symbol, whitespace, control or format character. */
const fold = (text: string) => text.normalize('NFKC').toLowerCase().replace(/[\p{P}\p{S}\p{Z}\s\p{Cc}\p{Cf}]/gu, '');
const genericTitles: ReadonlySet<string> = new Set(GENERIC_TRACK_TITLES.map(fold));

/** Cleaned like tag text (format characters removed, control characters as spaces, NFC, whitespace collapsed); null for a link, an empty or over-long text, or a lone surrogate. */
function cleanTrackTitle(raw: unknown): string | null {
    if (typeof raw !== 'string' || raw.length > 4 * METADATA_LOOKUP_LIMITS.termLength + 64) return null;
    try { return cleanLookupTerm(raw.replace(/\p{Cf}/gu, '').replace(/\p{Cc}/gu, ' '), METADATA_LOOKUP_LIMITS.termLength); } catch { return null; }
}

const brackets = [['(', ')'], ['[', ']'], ['（', '）'], ['【', '】']] as const;
const dashes = [' - ', ' – ', ' — '] as const;
/**
 * The last trailing segment of cleaned text with the trimmed text before it: a bracketed group without a nested bracket of its kind,
 * else the text after the last spaced dash; null without one.
 */
function trailingSegment(text: string): { before: string; segment: string } | null {
    for (const [open, close] of brackets) {
        if (!text.endsWith(close)) continue;
        const at = text.lastIndexOf(open), segment = at < 0 ? null : text.slice(at + open.length, text.length - close.length);
        if (segment !== null && !segment.includes(close)) return { before: text.slice(0, at).trim(), segment };
    }
    const at = Math.max(...dashes.map(dash => text.lastIndexOf(dash)));
    return at < 0 ? null : { before: text.slice(0, at).trim(), segment: text.slice(at + 3) };
}
const versionMarker = /\b(?:instrumental|inst|off[\s-]?vocal|karaoke|backing\s+track)\b|オフボーカル|カラオケ|インスト|伴奏|纯音乐|純音樂|반주|연주곡/iu;
/** `MR` (an accompaniment track) only in upper case and not followed by a period, so a name such as `Mr. Big` marks nothing. */
const mrMarker = /(?<![\p{L}\p{N}])MR(?![\p{L}\p{N}.])/u;
const noteWord = /\b(?:feat|ft|featuring|remaster|remastered|version|ver|edit|mix|remix|live|mono|stereo|acoustic)\b/iu;
/**
 * Peels at most three trailing segments, each compared in NFKC form and counted only with text before it: one naming an
 * instrumental, off-vocal or karaoke version marks the title (checked before any note is removed, so `Song (Instrumental Version)`
 * is marked, not reduced), one holding a note word is removed, and any other ends the peeling.
 */
function peelTrackTitle(cleaned: string): { base: string; versionMarked: boolean } {
    let base = cleaned;
    for (let peeled = 0; peeled < 3; peeled++) {
        const found = trailingSegment(base);
        if (!found || !found.before) break;
        const segment = found.segment.normalize('NFKC');
        if (versionMarker.test(segment) || mrMarker.test(segment)) return { base, versionMarked: true };
        if (!noteWord.test(segment)) break;
        base = found.before;
    }
    return { base, versionMarked: false };
}

const audioExtension = /\.(?:mp3|flac|m4a|aac|wav|ogg|opus|aiff)$/i;
const trackNumberPrefix = /^\d{1,3}\s*[-._)]\s*/;
/**
 * Whether a cleaned title looks like a file name: equal, ignoring case, to the member's retained original filename with or without
 * its extension, ending in an audio file extension, starting with a track number and separator, or without whitespace and either
 * holding an underscore or made only of printable ASCII with a run of three digits (`REC0001`; `東京2020` is kept).
 */
function fileNameShaped(cleaned: string, originalFileName: unknown): boolean {
    const title = cleaned.toLowerCase();
    if (typeof originalFileName === 'string' && originalFileName.length <= 1024) {
        const name = originalFileName.normalize('NFC').replace(/\s+/gu, ' ').trim().toLowerCase();
        if (name && (title === name || title === name.replace(/\.[^.\s]{1,8}$/u, ''))) return true;
    }
    if (audioExtension.test(cleaned) || trackNumberPrefix.test(cleaned)) return true;
    return !/\s/u.test(cleaned) && (cleaned.includes('_') || (/^[\x21-\x7e]+$/.test(cleaned) && /\d{3,}/.test(cleaned)));
}

/** A title's text as it is compared and searched: cleaned and without its trailing notes; null when it does not clean. */
export function trackTitleText(raw: unknown): string | null {
    const cleaned = cleanTrackTitle(raw);
    return cleaned ? peelTrackTitle(cleaned).base || null : null;
}

/** A Han, Hiragana, Katakana or Hangul character, or a letter those scripts share (`ー`, `ｰ`, `〆`, the kana iteration marks). */
const heavy = /[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}]|(?=\p{L})[\p{scx=Han}\p{scx=Hira}\p{scx=Kana}\p{scx=Hang}]/u;
const counted = /[\p{L}\p{N}]/u;
/** Each Han, kana or Hangul character (`heavy`) weighs two, every other letter or digit one, anything else nothing; a non-string none. */
export function trackTitleWeight(text: unknown): number {
    if (typeof text !== 'string') return 0;
    let weight = 0;
    for (const character of text) weight += heavy.test(character) ? 2 : counted.test(character) ? 1 : 0;
    return weight;
}

/**
 * The distinctive titles of `members` (source order, which is Album order), heaviest first, then in Album order, each fold once:
 * the full ranked list, never capped (the planner keeps at most two). A member is skipped when its title does not clean, marks an
 * instrumental, off-vocal or karaoke version, looks like a file name, is only digits and punctuation or a generic title once its
 * notes and trailing digits are removed, equals the Album title or the submitted text (each without its notes), occurs more than
 * once in the Album (its whole cleaned title folded, so every member that has it is skipped), or weighs less than
 * TRACK_TITLE_MIN_WEIGHT. A member that is no record, or whose title is no string, gives nothing; a non-string Artist reads as null.
 */
export function distinctiveTrackTitles(members: readonly unknown[], context: { albumTitle: unknown; submittedText?: unknown }): DistinctiveTrackTitle[] {
    const read = (Array.isArray(members) ? members : []).map(member => isRecord(member) && typeof member.title === 'string'
        ? { member, cleaned: cleanTrackTitle(member.title) } : null);
    const occurrences = new Map<string, number>();
    for (const entry of read) if (entry?.cleaned) occurrences.set(fold(entry.cleaned), (occurrences.get(fold(entry.cleaned)) ?? 0) + 1);
    const excluded = [context.albumTitle, context.submittedText].map(trackTitleText).filter((text): text is string => text !== null).map(fold);
    const eligible: (DistinctiveTrackTitle & { order: number })[] = [];
    read.forEach((entry, order) => {
        if (!entry?.cleaned) return;
        const { base, versionMarked } = peelTrackTitle(entry.cleaned);
        if (versionMarked || fileNameShaped(entry.cleaned, entry.member.originalFileName)) return;
        const folded = fold(base);
        if (/^\p{N}*$/u.test(folded) || /^[\p{N}\p{P}\p{S}\p{Z}\s]*$/u.test(base) || genericTitles.has(folded.replace(/\p{N}+$/u, ''))) return;
        if (excluded.includes(folded) || (occurrences.get(fold(entry.cleaned)) ?? 0) > 1) return;
        const weight = trackTitleWeight(base);
        if (weight < TRACK_TITLE_MIN_WEIGHT) return;
        eligible.push({ text: base, artist: typeof entry.member.artist === 'string' ? entry.member.artist : null, weight, order });
    });
    eligible.sort((left, right) => right.weight - left.weight || left.order - right.order);
    const seen = new Set<string>(), ranked: DistinctiveTrackTitle[] = [];
    for (const { text, artist, weight } of eligible) {
        if (seen.has(fold(text))) continue;
        seen.add(fold(text)); ranked.push({ text, artist, weight });
    }
    return ranked;
}
